    self.process = subprocess.Popen(
        [executable_path] + parameters, 
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
    )

  def check_status(self):
    """Checks and prints the current status of the miner."""
    try:
      status = self.process.communicate()[0].decode("utf-8")
      print(f"Miner: {status}")
    except:
      print(f"Miner: (Error checking status)")

  def stop(self):
    """Stops the miner process."""
    if self.process is not None:
      self.process.terminate()
    self.process = None

  def is_running(self):
    """Checks if the miner is running."""
    return self.process is not None


